package dev.zomboid.isotacz;
import net.minecraft.world.phys.Vec3;import net.minecraft.client.Minecraft;import com.cleannrooster.dungeons_iso.mod.Mod;
public class Checks {
 static int n;static void check(boolean b,String message){n++;if(!b)throw new AssertionError(message);}static void near(double a,double b,String s){check(Math.abs(a-b)<.001,s+": "+a+" vs "+b);}
 public static class Pos {final int x,y,z;Pos(int a,int b,int c){x=a;y=b;z=c;}public int getX(){return x;}public int getY(){return y;}public int getZ(){return z;}public boolean equals(Object o){return o instanceof Pos p&&p.x==x&&p.y==y&&p.z==z;}public int hashCode(){return x*31+z;}}
 public static class Hit {Vec3 point;String type;Pos pos;Object entity;Hit(Vec3 v,String t){point=v;type=t;pos=new Pos((int)Math.floor(v.x),(int)Math.floor(v.y),(int)Math.floor(v.z));}public Vec3 getLocation(){return point;}public String getType(){return type;}public Pos getBlockPos(){return pos;}public Object getEntity(){return entity;}}
 public static class State {String id;State(String s){id=s;}public String getBlock(){return id;}}
 public static class World {public boolean container=true,occluded;public String id="minecraft:chest";public double fraction=1;public Hit clip(net.minecraft.world.level.ClipContext c){Vec3 a=(Vec3)c.a,b=(Vec3)c.b;return new Hit(a.add(b.subtract(a).scale(occluded?.1:fraction)),occluded||fraction<1?"BLOCK":"MISS");}public State getBlockState(Object pos){return new State(id);}}
 public static class Input {public float forwardImpulse,leftImpulse;}
 public static class Entity {public Vec3 position=new Vec3(0,0,2);}
 public static class Player {public final Input input=new Input();public boolean gun=true;public float yaw,pitch,yBodyRot;public Vec3 getEyePosition(){return new Vec3(0,1.6,0);}public Object getMainHandItem(){return gun;}public float getXRot(){return pitch;}public float getYRot(){return yaw;}public float getYHeadRot(){return yaw;}public void setXRot(float p){pitch=p;}public void setYRot(float y){yaw=y;}public void setYHeadRot(float y){}public double blockInteractionRange(){return 4.5;}public boolean canInteractWithEntity(Entity e,double extra){return getEyePosition().distanceTo(e.position)<=3;}public void swing(Object hand){}}
 public static class Callback {public boolean canceled;public Object result;public void cancel(){canceled=true;}public void setReturnValue(Object value){result=value;}}
 public static class Game {public int blocks,entities;public Result useItemOn(Object p,Object hand,Object hit){blocks++;return new Result();}public Result interact(Object p,Object entity,Object hand){entities++;return new Result();}}
 public static class Result {public boolean shouldSwing(){return false;}}
 public static class Camera {Vec3 pos=new Vec3(0,8,-8);public Vec3 getPosition(){return pos;}public void setPosition(Vec3 p){pos=p;}}
 public static void main(String[] args){
  for(double a:new double[]{-1000,-720,-360,0,360,720,1000}){double w=Rules.wrap(a);check(w>=-180&&w<180,"wrapped angles bounded");}
  for(double[] d:new double[][]{{1,0},{-1,0},{0,1},{0,-1},{.707,.707},{-.707,.707},{.707,-.707},{-.707,-.707}})check(Rules.sprint(d[0],d[1]),"all eight sprint directions");check(!Rules.sprint(.3,.3),"slow movement cannot sprint");check(!Rules.sprint(0,0),"stationary cannot sprint");
  near(Rules.step(179,-179,.05),181,"short rotation across wrap");near(Rules.step(0,180,.05),-3.5,"bounded rotation speed");double[] s={1,.8,.8,1,1,1,1,1};check(Rules.choose(s)==0,"clear camera stays stable");s=new double[]{.2,.95,.7,.3,.1,.3,.7,.9};check(Rules.choose(s)==1,"blocked camera selects clear nearby view");s=new double[]{.6,.7,.65,.6,.6,.6,.6,.6};check(Rules.choose(s)==0,"small improvement does not cause jitter");
  near(Rules.project(0,0,1,800,600)[0],400,"reticle screen center x");near(Rules.project(0,0,1,800,600)[1],300,"reticle screen center y");check(Rules.project(0,0,-1,800,600)==null,"behind camera hidden");check(Rules.project(2,0,1,800,600)==null,"offscreen hidden");
  Minecraft mc=Minecraft.INSTANCE;Player p=new Player();World world=new World();Game game=new Game();mc.player=p;mc.level=world;mc.gameMode=game;Hit hit=new Hit(new Vec3(2,0,3),"BLOCK");Mod.crosshairTarget=hit;Bridge.aim();check(p.pitch>0,"gun aims down to cursor despite block target");near(Mod.livingPitch,0,"native render interpolation captures previous pitch");near(p.yBodyRot,p.yaw,"gun body faces aim independently of movement");double yaw=p.yaw,pitch=p.pitch;p.yaw+=3;p.pitch-=2;Bridge.aim();near(p.yaw,yaw+3,"yaw recoil retained");near(p.pitch,pitch-2,"pitch recoil retained");check(Bridge.suppressNativeLook(p),"native look bypassed only for local gun");p.gun=false;check(!Bridge.suppressNativeLook(p),"normal equipment retains native look");p.gun=true;
  p.input.leftImpulse=1;Callback cb=new Callback();check(Bridge.sprintOverride(p,cb)&&Boolean.TRUE.equals(cb.result),"local player can sprint sideways");p.input.leftImpulse=0;cb=new Callback();Bridge.sprintOverride(p.input,cb);check(Boolean.FALSE.equals(cb.result),"input stops sprint when stationary");cb=new Callback();check(!Bridge.sprintOverride(new Object(),cb),"unrelated input untouched");
  check(Bridge.interactable(mc,hit),"chest under cursor interactable");world.container=false;world.id="doomsday_decoration:remains_1";check(Bridge.interactable(mc,hit),"corpse block works without menu provider");world.id="zombie_remains_loot:skeletal_remains";check(Bridge.interactable(mc,hit),"skeletal remains selectable");world.id="minecraft:stone";check(!Bridge.interactable(mc,hit),"plain stone not interactive");world.container=true;world.occluded=true;check(!Bridge.interactable(mc,hit),"wall blocks interaction");world.occluded=false;check(!Bridge.interactable(mc,new Hit(new Vec3(100,1,100),"BLOCK")),"range enforced independent of native iso range bypass");
  cb=new Callback();Bridge.mouse(1,1,1,0,cb);check(cb.canceled&&game.blocks==1,"right click uses ordinary gameMode block interaction exactly once");cb=new Callback();Bridge.mouse(1,1,0,0,cb);check(cb.canceled,"claimed press release consumed");Mod.crosshairTarget=new Hit(new Vec3(2,1,3),"MISS");cb=new Callback();Bridge.mouse(1,1,1,0,cb);check(!cb.canceled&&game.blocks==1,"no target preserves gun right click");Mod.crosshairTarget=hit;cb=new Callback();Bridge.mouse(2,1,1,0,cb);check(!cb.canceled,"other window ignored");mc.screen=new Object();cb=new Callback();Bridge.mouse(1,1,1,0,cb);check(!cb.canceled,"GUI clicks preserved");mc.screen=null;
  de.maxhenkel.corpse.entities.CorpseEntity corpse=new de.maxhenkel.corpse.entities.CorpseEntity();Hit eh=new Hit(corpse.position,"ENTITY");eh.entity=corpse;check(Bridge.interactable(mc,eh),"corpse entity selectable");Mod.crosshairTarget=eh;cb=new Callback();Bridge.mouse(1,1,1,0,cb);check(cb.canceled&&game.entities==1,"corpse right click uses native entity event path");eh.entity=new Entity();check(!Bridge.interactable(mc,eh),"living targets do not steal aim");
  Camera camera=new Camera();double original=world.fraction=.5;Bridge.finishCamera(camera);check(camera.pos.distanceTo(p.getEyePosition())<6,"camera kept on near side of obstacle");check(camera.pos.y>1.6,"collision correction retains elevated angle");world.fraction=1;camera=new Camera();Vec3 before=camera.pos;Bridge.finishCamera(camera);check(camera.pos.distanceTo(p.getEyePosition())<before.distanceTo(p.getEyePosition()),"camera restores distance smoothly after obstruction");Bridge.cameraDistance=0;Bridge.finishCamera(camera);Vec3 clear=camera.pos;Bridge.cameraDistance=0;Bridge.finishCamera(camera);check(camera.pos==clear,"clear camera position unchanged");
  Mod.enabled=false;check(!Bridge.suppressNativeLook(p),"disabled iso gun unaffected");cb=new Callback();Bridge.sprintOverride(p,cb);check(cb.result==null,"disabled iso sprint untouched");Bridge.cancelScope(cb);check(!cb.canceled,"disabled iso scope retained");mc.hitResult=hit;Bridge.mouseClaimed=false;cb=new Callback();Bridge.mouse(1,1,1,0,cb);check(cb.canceled&&game.blocks==2,"normal view also opens chest with right click while armed");mc.hitResult=new Hit(new Vec3(2,1,3),"MISS");Bridge.mouseClaimed=false;cb=new Callback();Bridge.mouse(1,1,1,0,cb);check(!cb.canceled,"normal view preserves right click aim without container");Mod.enabled=true;Bridge.cancelScope(cb);check(cb.canceled,"scope zoom canceled in iso only");
  Bridge.sessionWorld=null;Mod.lastPerspective=net.minecraft.client.CameraType.FIRST_PERSON;Bridge.session();check(!Mod.enabled,"world entry disables iso");check(mc.options.cameraType==net.minecraft.client.CameraType.FIRST_PERSON,"world entry restores normal view");check(mc.mouseHandler.releases==1&&mc.mouseHandler.grabs==1,"normal mouse recaptured after iso session");check(mc.levelRenderer.refreshes==1,"culled terrain refreshed on exit");var config=com.cleannrooster.dungeons_iso.config.Config.GSON.instance();check(!config.onStartup&&!config.force&&!config.showFirstTimeGui,"old startup config cannot force mode");Mod.enabled=true;Bridge.session();check(Mod.enabled,"manual toggle stays enabled inside same world");mc.level=null;Bridge.session();mc.level=new World();Bridge.session();check(!Mod.enabled,"rejoining starts disabled again");Mod.enabled=true;mc.level=new World();Bridge.session();check(!Mod.enabled,"changing worlds starts disabled");Mod.enabled=true;config.force=true;config.onStartup=true;Bridge.session();check(Mod.enabled&&!config.force&&!config.onStartup,"startup flags suppressed without disabling manual toggle");
  System.out.println("Passed "+n+" geometry, aim, sprint, collision, and interaction checks (API doubles)");
 }
}
